#include "unity.h"
#include "helpers.h"
#include <time.h>

void setUp(void) { }
void tearDown(void) { }

void unit_test_get_clock_diff_positive_difference(void) {
    clock_t start_t = 1000;
    clock_t end_t = 5000;
    double expected = (double)(end_t - start_t) / (double)CLOCKS_PER_SEC;

    double result = get_clock_diff(start_t, end_t);

    TEST_ASSERT_EQUAL_DOUBLE(expected, result);
}

void unit_test_get_clock_diff_zero_difference(void) {
    clock_t start_t = 3000;
    clock_t end_t = 3000;
    double expected = 0.0;

    double result = get_clock_diff(start_t, end_t);

    TEST_ASSERT_EQUAL_DOUBLE(expected, result);
}

void unit_test_get_clock_diff_end_greater_than_start(void) {
    clock_t start_t = 5000;
    clock_t end_t = 1000;
    double expected = (double)(end_t - start_t) / (double)CLOCKS_PER_SEC;

    double result = get_clock_diff(start_t, end_t);

    TEST_ASSERT_EQUAL_DOUBLE(expected, result);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_get_clock_diff_positive_difference);
    RUN_TEST(unit_test_get_clock_diff_zero_difference);
    RUN_TEST(unit_test_get_clock_diff_end_greater_than_start);
    return UNITY_END();
}
